(function () {
'use strict';
var CFG = window.VP_CONFIG || {};
window.dataLayer = window.dataLayer || [];
function track(event, params) {
var details = params || {};
window.dataLayer.push(Object.assign({ event: event }, details));
if (typeof window.gtag === 'function') window.gtag('event', event, details);
if (CFG.yandexMetrika && typeof window.ym === 'function') window.ym(CFG.yandexMetrika, 'reachGoal', event, details);
}
window.vpTrack = track;
function initAnalytics() {
try {
var firstTouch = new URLSearchParams(location.search);
['utm_source', 'utm_medium', 'utm_campaign', 'utm_term', 'utm_content'].forEach(function (key) {
var storageKey = 'vp_' + key;
if (!sessionStorage.getItem(storageKey)) {
var firstValue = firstTouch.get(key);
if (firstValue) sessionStorage.setItem(storageKey, firstValue.slice(0, 120));
}
});
if (!sessionStorage.getItem('vp_referrer') && document.referrer) {
var firstReferrer = new URL(document.referrer);
sessionStorage.setItem('vp_referrer', (firstReferrer.origin + firstReferrer.pathname).slice(0, 300));
}
} catch (_) {}
if (CFG.ga4 && /^G-[A-Z0-9]+$/.test(CFG.ga4)) {
var s = document.createElement('script');
s.async = true;
s.src = 'https://www.googletagmanager.com/gtag/js?id=' + encodeURIComponent(CFG.ga4);
document.head.appendChild(s);
window.dataLayer.push({ 'gtm.start': Date.now(), event: 'gtm.js' });
window.gtag = function () { window.dataLayer.push(arguments); };
window.gtag('js', new Date());
window.gtag('config', CFG.ga4);
}
if (CFG.yandexMetrika && /^\d+$/.test(String(CFG.yandexMetrika))) {
(function (m, e, t, r, i, k, a) {
m[i] = m[i] || function () { (m[i].a = m[i].a || []).push(arguments); };
m[i].l = 1 * new Date();
k = e.createElement(t); a = e.getElementsByTagName(t)[0];
k.async = true; k.src = 'https://mc.yandex.ru/metrika/tag.js'; a.parentNode.insertBefore(k, a);
})(window, document, 'script', 'mc.yandex.ru', 'ym');
window.ym(CFG.yandexMetrika, 'init', { webvisor: false, clickmap: false, trackLinks: true });
}
}
function initMenu() {
var burger = document.querySelector('[data-burger]');
var menu = document.querySelector('[data-mobile-menu]');
if (!burger || !menu) return;
function close() {
burger.setAttribute('aria-expanded', 'false');
menu.classList.remove('open');
document.body.style.overflow = '';
}
burger.addEventListener('click', function () {
var open = burger.getAttribute('aria-expanded') === 'true';
burger.setAttribute('aria-expanded', String(!open));
menu.classList.toggle('open', !open);
document.body.style.overflow = open ? '' : 'hidden';
});
menu.addEventListener('click', function (e) { if (e.target.closest('a')) close(); });
document.addEventListener('keydown', function (e) { if (e.key === 'Escape') close(); });
}
function initCitySelector() {
var links = document.querySelectorAll('[data-city-link]');
if (!links.length) return;
var valid = {};
links.forEach(function (link) { valid[link.getAttribute('data-city-link')] = link.textContent.trim(); });
var city = document.body.getAttribute('data-city-page') || '';
try {
var saved = localStorage.getItem('vp_city');
if (city && valid[city]) localStorage.setItem('vp_city', city);
else if (saved && valid[saved]) city = saved;
} catch (e) {}
if (!city || !valid[city]) city = 'kazan';
document.querySelectorAll('[data-city-current]').forEach(function (el) { el.textContent = valid[city] || 'Казань'; });
if (!document.body.getAttribute('data-city-page')) {
var homeCity = document.querySelector('[data-home-city]');
var cityIn = {
kazan: 'Казани', penza: 'Пензе', 'nizhniy-novgorod': 'Нижнем Новгороде',
saratov: 'Саратове', krasnodar: 'Краснодаре', voronezh: 'Воронеже',
moskva: 'Москве', 'sankt-peterburg': 'Санкт-Петербурге',
saransk: 'Саранске', ulyanovsk: 'Ульяновске'
};
if (homeCity && cityIn[city]) {
homeCity.textContent = cityIn[city];
document.title = 'Натяжные потолки в ' + cityIn[city] + ' под ключ | Всем-Потолок';
}
}
links.forEach(function (link) {
link.addEventListener('click', function () {
var selected = link.getAttribute('data-city-link');
try { localStorage.setItem('vp_city', selected); } catch (e) {}
track('city_select', { city: selected });
});
});
document.addEventListener('click', function (e) {
if (e.target.closest('.city-select')) return;
document.querySelectorAll('.city-select[open]').forEach(function (el) { el.removeAttribute('open'); });
});
}
function initReveal() {
var els = document.querySelectorAll('.reveal');
if (!('IntersectionObserver' in window)) {
els.forEach(function (el) { el.classList.add('in'); });
return;
}
var io = new IntersectionObserver(function (entries) {
entries.forEach(function (en) {
if (en.isIntersecting) { en.target.classList.add('in'); io.unobserve(en.target); }
});
}, { rootMargin: '0px 0px -8% 0px', threshold: 0.08 });
document.documentElement.classList.add('js');
els.forEach(function (el) { io.observe(el); });
}
var lastFocus = null;
function openModal(id, payload) {
var m = document.querySelector('[data-modal="' + id + '"]');
if (!m) return;
lastFocus = document.activeElement;
if (payload && payload.product) {
var slot = m.querySelector('[data-modal-product]');
if (slot) slot.textContent = payload.product;
var input = m.querySelector('input[name="interest"]');
if (input) input.value = payload.product;
}
m.classList.add('open');
m.removeAttribute('aria-hidden');
document.body.style.overflow = 'hidden';
var f = m.querySelector('input,button,select,textarea');
if (f) setTimeout(function () { f.focus(); }, 60);
track('modal_open', { modal: id });
}
function closeModal(m) {
m.classList.remove('open');
m.setAttribute('aria-hidden', 'true');
document.body.style.overflow = '';
if (lastFocus) lastFocus.focus();
}
function initModals() {
document.addEventListener('click', function (e) {
var opener = e.target.closest('[data-modal-open]');
if (opener) {
e.preventDefault();
openModal(opener.getAttribute('data-modal-open'), { product: opener.getAttribute('data-product') || '' });
return;
}
var m = e.target.closest('[data-modal]');
if (m && (e.target.classList.contains('modal__bg') || e.target.closest('[data-modal-close]'))) closeModal(m);
});
document.addEventListener('keydown', function (e) {
if (e.key === 'Escape') {
var open = document.querySelector('.modal.open');
if (open) closeModal(open);
}
});
}
window.vpOpenModal = openModal;
function formatPhone(v) {
var d = v.replace(/\D/g, '');
if (d.startsWith('8')) d = '7' + d.slice(1);
if (d.startsWith('9') && d.length <= 10) d = '7' + d;
d = d.slice(0, 11);
if (!d) return '';
var out = '+7';
if (d.length > 1) out += ' (' + d.slice(1, 4);
if (d.length >= 4) out += ') ' + d.slice(4, 7);
if (d.length >= 7) out += '-' + d.slice(7, 9);
if (d.length >= 9) out += '-' + d.slice(9, 11);
return out;
}
function initPhoneInputs() {
document.querySelectorAll('input[type="tel"]').forEach(function (inp) {
inp.setAttribute('inputmode', 'tel');
inp.setAttribute('autocomplete', 'tel');
inp.addEventListener('input', function () {
var d = inp.value.replace(/\D/g, '');
if (d.length || inp.value === '') inp.value = formatPhone(inp.value);
});
});
}
function phoneValid(v) {
return v.replace(/\D/g, '').length === 11;
}
function setFormState(form, state) {
var btn = form.querySelector('button[type="submit"]');
if (!btn) return;
if (state === 'loading') {
btn.disabled = true;
btn.dataset.label = btn.dataset.label || btn.innerHTML;
btn.innerHTML = '<span class="spin" aria-hidden="true"></span> Отправляем…';
} else {
btn.disabled = false;
if (btn.dataset.label) btn.innerHTML = btn.dataset.label;
}
}
function showMsg(form, type, text) {
var box = form.querySelector('[data-form-msg]');
if (!box) return;
box.className = 'form-msg ' + type;
box.textContent = text;
box.setAttribute('role', type === 'ok' ? 'status' : 'alert');
}
function showContactFallback(form) {
var box = form.querySelector('[data-form-msg]');
if (!box) return;
var phone = document.querySelector('a[href^="tel:"]');
var whatsapp = document.querySelector('a.msg-btn[data-messenger="whatsapp"]');
var actions = document.createElement('div');
actions.className = 'form-msg__actions';
if (phone) {
var call = document.createElement('a');
call.href = phone.href;
call.textContent = 'Позвонить';
actions.appendChild(call);
}
if (whatsapp) {
var message = document.createElement('a');
message.href = whatsapp.href;
message.dataset.messenger = 'whatsapp';
message.target = '_blank';
message.rel = 'noopener';
message.textContent = 'Написать в WhatsApp';
actions.appendChild(message);
}
if (actions.childNodes.length) box.appendChild(actions);
}
function clearMsg(form) {
var box = form.querySelector('[data-form-msg]');
if (box) { box.className = 'form-msg'; box.textContent = ''; }
}
function validate(form) {
var ok = true;
form.querySelectorAll('[required]').forEach(function (f) {
var wrap = f.closest('.field');
var bad = false;
if (f.type === 'checkbox') bad = !f.checked;
else if (f.type === 'tel') bad = !phoneValid(f.value);
else bad = !f.value.trim();
if (wrap) wrap.classList.toggle('invalid', bad);
if (f.type !== 'checkbox') f.setAttribute('aria-invalid', bad ? 'true' : 'false');
if (bad && ok) { f.focus(); ok = false; } else if (bad) ok = false;
});
return ok;
}
function collectPayload(form) {
var data = {};
new FormData(form).forEach(function (v, k) { data[k] = v; });
data.form = form.dataset.form || '';
data.page = location.pathname;
try { data.referrer = sessionStorage.getItem('vp_referrer') || ''; } catch (_) { data.referrer = ''; }
var attribution = {};
['utm_source', 'utm_medium', 'utm_campaign', 'utm_term', 'utm_content'].forEach(function (key) {
var value = new URLSearchParams(location.search).get(key);
try {
var stored = sessionStorage.getItem('vp_' + key);
if (value && !stored) {
stored = value.slice(0, 120);
sessionStorage.setItem('vp_' + key, stored);
}
value = stored || value;
} catch (_) {}
if (value) attribution[key] = value.slice(0, 120);
});
if (Object.keys(attribution).length) data.utm = attribution;
return data;
}
function sendLead(payload, attempt) {
var endpoint = CFG.formEndpoint || '/backend/forms.php';
return fetch(endpoint, {
method: 'POST',
headers: { 'Content-Type': 'application/json', 'Accept': 'application/json' },
body: JSON.stringify(payload)
}).then(function (r) {
return r.json().catch(function () { return {}; }).then(function (body) {
if (!r.ok) throw new Error(body.message || 'Не удалось отправить заявку. Попробуйте ещё раз.');
return body;
});
}).then(function (j) {
if (j && j.status === 'error') throw new Error(j.message || 'server error');
return j;
}).catch(function (err) {
if (!attempt && err instanceof TypeError) return sendLead(payload, true);
throw err;
});
}
function initForms() {
document.addEventListener('submit', function (e) {
var form = e.target.closest('form[data-form]');
if (!form) return;
e.preventDefault();
clearMsg(form);
if (form.querySelector('input[name="company_url"]') && form.querySelector('input[name="company_url"]').value) return;
var t0 = form.dataset.t0 ? Number(form.dataset.t0) : 0;
if (t0 && Date.now() - t0 < 1200) return;
if (!validate(form)) {
form.dataset.t0 = String(Date.now() - 5000);
showMsg(form, 'err', 'Проверьте выделенные поля.');
track('form_error', { form: form.dataset.form });
return;
}
var payload = collectPayload(form);
setFormState(form, 'loading');
sendLead(payload, false).then(function () {
setFormState(form, 'ready');
showMsg(form, 'ok', form.dataset.success || 'Заявка отправлена! Специалист свяжется с вами в рабочее время (с 9:00 до 21:00).');
track('form_submit', { form: form.dataset.form, interest: payload.interest || '' });
form.reset();
delete form.dataset.t0;
if (form.closest('.modal')) setTimeout(function () { closeModal(form.closest('.modal')); }, 2600);
}).catch(function (err) {
setFormState(form, 'ready');
if (err instanceof TypeError) {
showMsg(form, 'err', 'Не удалось соединиться с сервером. Заявка сохранена на устройстве и отправится автоматически, когда соединение восстановится.');
showContactFallback(form);
queueOffline(payload);
track('form_error', { form: form.dataset.form, reason: 'network' });
} else {
showMsg(form, 'err', (err && err.message ? err.message : 'Не удалось передать заявку.') + ' Телефон: ' + (CFG.phoneDisplay || ''));
showContactFallback(form);
track('form_error', { form: form.dataset.form, reason: 'server' });
}
});
});
document.addEventListener('focusin', function (e) {
var form = e.target.closest('form[data-form]');
if (form && !form.dataset.t0) form.dataset.t0 = String(Date.now());
});
function queueOffline(payload) {
try {
var q = JSON.parse(localStorage.getItem('vp_leads') || '[]');
q.push(payload);
localStorage.setItem('vp_leads', JSON.stringify(q));
} catch (e) {}
}
function flushQueue() {
try {
var q = JSON.parse(localStorage.getItem('vp_leads') || '[]');
if (!q.length || !navigator.onLine) return;
var p = q.shift();
localStorage.setItem('vp_leads', JSON.stringify(q));
sendLead(p, false).then(function () { flushQueue(); }).catch(function () {
q.unshift(p); localStorage.setItem('vp_leads', JSON.stringify(q));
});
} catch (e) {}
}
window.addEventListener('online', flushQueue);
setInterval(flushQueue, 60000);
flushQueue();
}
function initClickTracking() {
document.addEventListener('click', function (e) {
var a = e.target.closest('a');
if (!a) return;
if (a.getAttribute('href') && a.getAttribute('href').indexOf('tel:') === 0) track('call_click', { href: a.getAttribute('href') });
if (a.classList.contains('msg-btn') || a.dataset.messenger) track('messenger_click', { messenger: a.dataset.messenger || '' });
if (a.dataset.modalOpen === 'calc' || a.getAttribute('href') === '/calculator/') track('calc_start', { source: 'link' });
});
}
function initScrollProgress() {
var bar = document.querySelector('[data-scroll-progress]');
if (!bar) return;
var tick = false;
function update() {
tick = false;
var h = document.documentElement;
var max = h.scrollHeight - h.clientHeight;
bar.style.width = (max > 0 ? (h.scrollTop / max) * 100 : 0) + '%';
}
window.addEventListener('scroll', function () {
if (!tick) { tick = true; requestAnimationFrame(update); }
}, { passive: true });
update();
}
function plural(n, forms) {
n = Math.abs(n) % 100; var n1 = n % 10;
if (n > 10 && n < 20) return forms[2];
if (n1 > 1 && n1 < 5) return forms[1];
if (n1 === 1) return forms[0];
return forms[2];
}
function initLiveStatus() {
var el = document.querySelector('[data-live-status]');
if (!el) return;
var txt = el.querySelector('[data-live-text]');
if (txt) txt.textContent = 'Заявки принимаем ежедневно';
}
function initYear() {
document.querySelectorAll('[data-year]').forEach(function (el) { el.textContent = new Date().getFullYear(); });
}
function initSlotPickers() {
document.querySelectorAll('[data-slot-picker]').forEach(function (picker) {
var hidden = picker.querySelector('input[name="slot"]');
function update() {
var d = picker.querySelector('[data-day].active');
var t = picker.querySelector('[data-time].active');
var dayText = d ? d.textContent.trim() : 'Ближайший день';
var timeText = t ? t.textContent.trim() : 'в удобное время';
if (hidden) hidden.value = dayText + ', ' + timeText;
}
picker.querySelectorAll('[data-day]').forEach(function (btn) {
btn.addEventListener('click', function () {
picker.querySelectorAll('[data-day]').forEach(function (b) { b.classList.remove('active'); });
btn.classList.add('active');
update();
});
});
picker.querySelectorAll('[data-time]').forEach(function (btn) {
btn.addEventListener('click', function () {
picker.querySelectorAll('[data-time]').forEach(function (b) { b.classList.remove('active'); });
btn.classList.add('active');
update();
});
});
update();
});
}
function initBeforeAfterSliders() {
document.querySelectorAll('.ba-slider').forEach(function (slider) {
var range = slider.querySelector('.ba-slider__range');
if (!range) return;
function setPos(v) { slider.style.setProperty('--pos', v + '%'); }
range.addEventListener('input', function () { setPos(range.value); });
range.addEventListener('change', function () { setPos(range.value); });
setPos(range.value || 50);
});
}
function initReviewsFilter() {
var filterContainer = document.querySelector('[data-reviews-filter]');
if (!filterContainer) return;
var buttons = filterContainer.querySelectorAll('.filter-btn');
var cards = document.querySelectorAll('[data-review-city]');
buttons.forEach(function (btn) {
btn.addEventListener('click', function () {
buttons.forEach(function (b) { b.classList.remove('active'); });
btn.classList.add('active');
var city = btn.dataset.filter;
cards.forEach(function (card) {
if (city === 'all' || card.dataset.reviewCity === city) {
card.style.display = '';
} else {
card.style.display = 'none';
}
});
});
});
}

function initJkExplorer() {
  var filterBtns = document.querySelectorAll('.jk-city-btn');
  var searchInput = document.getElementById('jkSearchInput');
  var cards = document.querySelectorAll('.jk-card');
  if (!cards.length) return;

  var currentCity = 'all';
  var currentSearch = '';

  function applyFilters() {
    cards.forEach(function(card) {
      var matchCity = (currentCity === 'all' || card.dataset.city === currentCity);
      var matchSearch = (!currentSearch || (card.dataset.name && card.dataset.name.toLowerCase().indexOf(currentSearch) !== -1));
      card.style.display = (matchCity && matchSearch) ? '' : 'none';
    });
  }

  filterBtns.forEach(function(btn) {
    btn.addEventListener('click', function() {
      filterBtns.forEach(function(b) {
        b.classList.remove('active');
        b.style.background = '';
        b.style.color = '';
      });
      btn.classList.add('active');
      btn.style.background = '#0E6B3C';
      btn.style.color = '#fff';
      currentCity = btn.dataset.city || 'all';
      applyFilters();
    });
  });

  if (searchInput) {
    searchInput.addEventListener('input', function() {
      currentSearch = searchInput.value.trim().toLowerCase();
      applyFilters();
    });
  }
}

window.applyJkPromo = function(jkName) {
  var measureSection = document.getElementById('measure') || document.querySelector('form');
  if (measureSection) {
    measureSection.scrollIntoView({ behavior: 'smooth' });
    var commentInput = measureSection.querySelector('input[name="comment"], textarea[name="comment"], input[name="name"]');
    var phoneInput = measureSection.querySelector('input[type="tel"]');
    if (commentInput) {
      commentInput.value = 'Скидка соседа: ' + jkName;
    }
    if (phoneInput) {
      setTimeout(function() { phoneInput.focus(); }, 600);
    }
  }
};

document.addEventListener('DOMContentLoaded', function () {
initAnalytics(); initMenu(); initCitySelector(); initReveal(); initModals();
initPhoneInputs(); initForms(); initClickTracking(); initYear(); initScrollProgress(); initLiveStatus();
initSlotPickers(); initBeforeAfterSliders(); initReviewsFilter(); initJkExplorer();
});
})();
